%%%-------------------------------------------------------------------
%%% @doc Sovereign Circuit Fabric — console HTTP server.
%%%
%%% A small hand-rolled HTTP/1.1 server on gen_tcp. It serves one
%%% stylesheet and one server-rendered page, and accepts form posts
%%% that dispatch commands to the exchange. There is no JavaScript
%%% and no external asset: every response is generated by BEAM.
%%%-------------------------------------------------------------------
-module(scf_http).

-export([start/1]).

start(Port) ->
    Pid = spawn(fun () -> listen(Port) end),
    {ok, Pid}.

listen(Port) ->
    {ok, LSock} = gen_tcp:listen(Port, [binary, {packet, raw},
                                        {active, false},
                                        {reuseaddr, true}]),
    accept(LSock).

accept(LSock) ->
    case gen_tcp:accept(LSock) of
        {ok, Sock} ->
            spawn(fun () -> handle(Sock) end),
            accept(LSock);
        {error, _} ->
            accept(LSock)
    end.

%%%-------------------------------------------------------------------
%%% Request handling
%%%-------------------------------------------------------------------

handle(Sock) ->
    case read_request(Sock) of
        {ok, Method, Target, Body} ->
            {Status, Headers, RespBody} = route(Method, Target, Body),
            send_response(Sock, Status, Headers, RespBody);
        error ->
            ok
    end,
    gen_tcp:close(Sock).

read_request(Sock) ->
    case read_headers(Sock, <<>>) of
        {ok, Head, Rest} ->
            Lines = binary:split(Head, <<"\r\n">>, [global]),
            [RequestLine | HeaderLines] = Lines,
            case binary:split(RequestLine, <<" ">>, [global]) of
                [Method, Target, _Version] ->
                    Headers = parse_headers(HeaderLines),
                    Len = case maps:find(<<"content-length">>, Headers) of
                              {ok, V} -> binary_to_integer(V);
                              error -> 0
                          end,
                    case read_body(Sock, Rest, Len) of
                        {ok, Body} ->
                            {ok, binary_to_list(Method),
                             binary_to_list(Target), Body};
                        error -> error
                    end;
                _ -> error
            end;
        error -> error
    end.

read_headers(Sock, Acc) ->
    case binary:split(Acc, <<"\r\n\r\n">>) of
        [Head, Rest] -> {ok, Head, Rest};
        [_] ->
            case gen_tcp:recv(Sock, 0, 15000) of
                {ok, Data} -> read_headers(Sock, <<Acc/binary, Data/binary>>);
                {error, _} -> error
            end
    end.

read_body(_Sock, Acc, Len) when byte_size(Acc) >= Len ->
    {ok, binary:part(Acc, 0, Len)};
read_body(Sock, Acc, Len) ->
    case gen_tcp:recv(Sock, 0, 15000) of
        {ok, Data} -> read_body(Sock, <<Acc/binary, Data/binary>>, Len);
        {error, _} -> error
    end.

parse_headers(Lines) ->
    lists:foldl(
      fun (Line, Acc) ->
              case binary:split(Line, <<": ">>) of
                  [K, V] -> Acc#{lower(K) => V};
                  _ -> Acc
              end
      end, #{}, Lines).

lower(Bin) ->
    << <<(lower_char(C))>> || <<C>> <= Bin >>.

lower_char(C) when C >= $A, C =< $Z -> C + 32;
lower_char(C) -> C.

send_response(Sock, Status, Headers, Body) ->
    Reason = case Status of
                 200 -> "OK";
                 303 -> "See Other";
                 404 -> "Not Found"
             end,
    Head = io_lib:format("HTTP/1.1 ~B ~s\r\nContent-Length: ~B\r\n"
                         "Connection: close\r\n~s\r\n",
                         [Status, Reason, iolist_size(Body),
                          [[K, ": ", V, "\r\n"] || {K, V} <- Headers]]),
    gen_tcp:send(Sock, [Head, Body]).

%%%-------------------------------------------------------------------
%%% Routing
%%%-------------------------------------------------------------------

route("GET", "/style.css", _Body) ->
    {200, [{"Content-Type", "text/css; charset=utf-8"}], scf_render:css()};
route("GET", Target, _Body) ->
    {Path, Query} = split_target(Target),
    case Path of
        "/" ->
            Params = parse_params(Query),
            View = scf_exchange:snapshot(),
            Opts = #{tab => maps:get("tab", Params, "fabric"),
                     sel => to_sel(maps:get("sel", Params, "")),
                     arm => maps:get("arm", Params, "") =:= "1"},
            {200, [{"Content-Type", "text/html; charset=utf-8"}],
             scf_render:page(View, Opts)};
        _ ->
            {404, [{"Content-Type", "text/plain; charset=utf-8"}],
             "Not found."}
    end;
route("POST", Target, Body) ->
    {Path, _Query} = split_target(Target),
    case Path of
        "/cmd" ->
            Params = parse_params(binary_to_list(Body)),
            Before = scf_exchange:snapshot(),
            TxId = maps:get("txid", Params,
                            "tx-" ++ integer_to_list(maps:get(next_tx, Before))),
            Cmd = build_cmd(Params, TxId),
            case Cmd of
                none ->
                    {303, [{"Location", "/?tab=fabric"}], <<>>};
                _ ->
                    {Ok, _Replay, _Detail} = scf_exchange:dispatch(Cmd),
                    After = scf_exchange:snapshot(),
                    Location = redirect_for(Params, Cmd, Ok, After),
                    {303, [{"Location", Location}], <<>>}
            end;
        _ ->
            {404, [{"Content-Type", "text/plain; charset=utf-8"}],
             "Not found."}
    end;
route(_Method, _Target, _Body) ->
    {404, [{"Content-Type", "text/plain; charset=utf-8"}], "Not found."}.

redirect_for(Params, Cmd, Ok, After) ->
    Type = maps:get(type, Cmd),
    Tab = maps:get("tab", Params, "fabric"),
    Sel = maps:get("sel", Params, ""),
    if Type =:= create andalso Ok ->
           "/?tab=circuits&sel=" ++
           integer_to_list(maps:get(next_id, After) - 1);
       Type =:= reset andalso Ok ->
           "/?tab=fabric";
       Type =:= pricing_vector ->
           "/?tab=ledger";
       true ->
           Base = "/?tab=" ++ Tab,
           case Sel of
               "" -> Base;
               _ -> Base ++ "&sel=" ++ Sel
           end
    end.

%%%-------------------------------------------------------------------
%%% Command construction from form fields. Unparsable integers fall
%%% back to values the model's own validation rejects, so the error
%%% text stays the model's.
%%%-------------------------------------------------------------------

build_cmd(Params, TxId) ->
    Type = maps:get("type", Params, ""),
    Cid = to_int(maps:get("cid", Params, ""), 0),
    case Type of
        "create" ->
            #{type => create, tx_id => TxId,
              src => maps:get("src", Params, ""),
              dst => maps:get("dst", Params, ""),
              bps => to_int(maps:get("bps", Params, ""), -1),
              priority => to_int(maps:get("priority", Params, ""), -1),
              qos => to_int(maps:get("qos", Params, ""), -1),
              tariff_id => to_int(maps:get("tariff_id", Params, ""), 0)};
        "tick" ->
            #{type => tick, tx_id => TxId};
        "inject" ->
            Base = #{type => inject, tx_id => TxId, cid => Cid,
                     payload_bytes => to_int(maps:get("payload_bytes", Params, ""), -1)},
            case maps:get("corrupt", Params, "") of
                "" -> Base;
                Corrupt -> Base#{corrupt => Corrupt}
            end;
        "fail_link" ->
            #{type => fail_link, tx_id => TxId,
              link_id => maps:get("link_id", Params, "")};
        "restore_link" ->
            #{type => restore_link, tx_id => TxId,
              link_id => maps:get("link_id", Params, "")};
        "revise_tariff" ->
            #{type => revise_tariff, tx_id => TxId,
              tariff_id => to_int(maps:get("tariff_id", Params, ""), 0),
              setup => to_int(maps:get("setup", Params, ""), -1)};
        "pricing_vector" ->
            #{type => pricing_vector, tx_id => TxId};
        "reset" ->
            #{type => reset, tx_id => TxId};
        "install" ->
            Base = #{type => install, tx_id => TxId, cid => Cid},
            case maps:find("fh", Params) of
                {ok, Fh} -> Base#{fault_hop => to_int(Fh, -1)};
                error -> Base
            end;
        "fail" ->
            #{type => fail, tx_id => TxId, cid => Cid,
              reason => maps:get("reason", Params, "OPERATOR")};
        T when T =:= "request" orelse T =:= "admit" orelse T =:= "reject"
               orelse T =:= "timeout" orelse T =:= "reserve"
               orelse T =:= "activate" orelse T =:= "drain"
               orelse T =:= "release" orelse T =:= "recycle" ->
            #{type => list_to_atom(T), tx_id => TxId, cid => Cid};
        _ ->
            none
    end.

%%%-------------------------------------------------------------------
%%% Parameter parsing (query string and form bodies)
%%%-------------------------------------------------------------------

split_target(Target) ->
    case string:split(Target, "?", all) of
        [Path] -> {Path, ""};
        [Path, Query] -> {Path, Query};
        [Path | Rest] -> {Path, string:join(Rest, "?")}
    end.

parse_params(S) ->
    Pairs = string:split(S, "&", all),
    lists:foldl(
      fun (Pair, Acc) ->
              case string:split(Pair, "=", all) of
                  [K] -> Acc#{url_decode(K) => ""};
                  [K, V] -> Acc#{url_decode(K) => url_decode(V)};
                  [K | Rest] -> Acc#{url_decode(K) => url_decode(string:join(Rest, "="))};
                  [] -> Acc
              end
      end, #{}, [P || P <- Pairs, P =/= ""]).

url_decode(S) -> url_decode(S, []).

url_decode([], Acc) -> lists:reverse(Acc);
url_decode([$+ | Rest], Acc) -> url_decode(Rest, [$\s | Acc]);
url_decode([$%, A, B | Rest], Acc) ->
    case hex2(A, B) of
        {ok, V} -> url_decode(Rest, [V | Acc]);
        error -> url_decode(Rest, [B, A, $% | Acc])
    end;
url_decode([C | Rest], Acc) -> url_decode(Rest, [C | Acc]).

hex2(A, B) ->
    case {hexval(A), hexval(B)} of
        {{ok, X}, {ok, Y}} -> {ok, X * 16 + Y};
        _ -> error
    end.

hexval(C) when C >= $0, C =< $9 -> {ok, C - $0};
hexval(C) when C >= $a, C =< $f -> {ok, C - $a + 10};
hexval(C) when C >= $A, C =< $F -> {ok, C - $A + 10};
hexval(_) -> error.

to_int(S, Default) ->
    case string:to_integer(string:trim(S)) of
        {N, ""} -> N;
        _ -> Default
    end.

to_sel("") -> none;
to_sel(S) ->
    case string:to_integer(S) of
        {N, ""} -> N;
        _ -> none
    end.
